export interface ConsumableIn {
  /** Scanned barcode of a formulary item (pharmacy stock, FEFO) */
  barcode?: string | null;
  drug_id?: number | null;
  qty: number | string;
  /** Non-stock items (e.g. vendor implant): description + costs */
  description?: string | null;
  asset_id?: number | null;
  unit_cost?: number | string | null;
  unit_retail?: number | string | null;
}

/** A consumable scanned into a surgery (or its reversal row; rows are never edited). */
export interface ConsumableOut {
  ot_consumable_id: number;
  booking_id: number;
  drug_id: number | null;
  drug_batch_id: number | null;
  asset_id: number | null;
  description: string;
  qty: number;
  unit_cost: number;
  line_cost: number;
  unit_retail: number;
  line_revenue: number;
  is_reversal: boolean;
  reverses_consumable_id: number | null;
  scanned_by: number;
  scanned_at: string;
}

export interface OtReasonIn {
  reason: string;
}

/** Patient in theater → 🔴 In-Surgery — POST /api/v1/ot/bookings/{booking_id}/start (who may call: holders of ot.booking.manage). */
export function startOtBookings(booking_id: number): Promise<OtBookingDetailOut> {
  return api<OtBookingDetailOut>("POST", `/ot/bookings/${booking_id}/start`, undefined);
}

/** Scan a consumable into the surgery — POST /api/v1/ot/bookings/{booking_id}/consumables (who may call: holders of ot.consumable.record). */
export function addConsumable(booking_id: number, body: ConsumableIn): Promise<ConsumableOut[]> {
  return api<ConsumableOut[]>("POST", `/ot/bookings/${booking_id}/consumables`, body, { idempotent: true });
}

/** Undo a mistaken scan (mirrored reversal row) — POST /api/v1/ot/consumables/{consumable_id}/reverse (who may call: holders of ot.consumable.record). */
export function reverseConsumable(consumable_id: number, body: OtReasonIn): Promise<ConsumableOut> {
  return api<ConsumableOut>("POST", `/ot/consumables/${consumable_id}/reverse`, body, { idempotent: true });
}

/** Surgery finished → 🟡 Cleaning-Prep — POST /api/v1/ot/bookings/{booking_id}/complete-surgery (who may call: holders of ot.booking.manage). */
export function completeSurgery(booking_id: number): Promise<OtBookingDetailOut> {
  return api<OtBookingDetailOut>("POST", `/ot/bookings/${booking_id}/complete-surgery`, undefined);
}

/** Theater cleaned → 🟢 Available — POST /api/v1/ot/bookings/{booking_id}/complete-cleaning (who may call: holders of ot.booking.manage). */
export function completeCleaning(booking_id: number): Promise<OtBookingDetailOut> {
  return api<OtBookingDetailOut>("POST", `/ot/bookings/${booking_id}/complete-cleaning`, undefined);
}

/** Booking with consumables and settlement — GET /api/v1/ot/bookings/{booking_id} (who may call: holders of ot.booking.view or ot.booking.manage). */
export function getBooking(booking_id: number): Promise<OtBookingDetailOut> {
  return api<OtBookingDetailOut>("GET", `/ot/bookings/${booking_id}`, undefined);
}
